const express = require('express');
const ldap = require('ldapjs');

const app = express();
app.use(express.json());

// LDAP connection configuration
const LDAP_URL = process.env.LDAP_URL || 'ldap://ldap.internal.corp:389';
const LDAP_BASE_DN = process.env.LDAP_BASE_DN || 'dc=corp,dc=internal';
const LDAP_BIND_DN = process.env.LDAP_BIND_DN || 'cn=svc-app,ou=services,dc=corp,dc=internal';
const LDAP_BIND_PW = process.env.LDAP_BIND_PW || '';

function createLdapClient() {
  const client = ldap.createClient({ url: LDAP_URL });
  return new Promise((resolve, reject) => {
    client.bind(LDAP_BIND_DN, LDAP_BIND_PW, (err) => {
      if (err) reject(err);
      else resolve(client);
    });
  });
}

// User lookup endpoint - used by internal tooling
app.get('/api/v1/users/lookup', async (req, res) => {
  const { username, department } = req.query;

  if (!username) {
    return res.status(400).json({ error: 'username parameter required' });
  }

  // Basic length check for sanity
  if (username.length > 128) {
    return res.status(400).json({ error: 'username too long' });
  }

  try {
    const client = await createLdapClient();

    // Build filter - department is optional refinement
    let filter;
    if (department) {
      filter = `(&(uid=${username})(department=${department}))`;
    } else {
      filter = `(uid=${username})`;
    }

    const opts = {
      filter: filter,
      scope: 'sub',
      attributes: ['uid', 'cn', 'mail', 'department', 'title', 'manager']
    };

    const results = [];

    client.search(LDAP_BASE_DN, opts, (err, searchRes) => {
      if (err) {
        client.unbind();
        return res.status(500).json({ error: 'Search failed' });
      }

      searchRes.on('searchEntry', (entry) => {
        results.push(entry.ppiObject || entry.object);
      });

      searchRes.on('error', (err) => {
        client.unbind();
        return res.status(500).json({ error: 'Search error' });
      });

      searchRes.on('end', () => {
        client.unbind();
        return res.json({ count: results.length, users: results });
      });
    });
  } catch (err) {
    console.error('LDAP connection error:', err.message);
    return res.status(503).json({ error: 'Directory service unavailable' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', service: 'user-directory-api' });
});

// Audit logging middleware (runs after response)
app.use((req, res, next) => {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    query: req.query,
    ip: req.headers['x-forwarded-for'] || req.ip,
    userAgent: req.headers['user-agent']
  }));
  next();
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`User directory API listening on port ${PORT}`);
});

module.exports = app;
